sub(p,'export async function findMemberById(','''/** The membership row only when it is live and active; anything else is a former member. */
export async function findActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const member = await findMember(orgId, userId);
  return member && member.archivedAt === null && member.status === "active"
    ? member
    : null;
}

/** The subset of `userIds` that are current (live, active) members of the org. */
export async function filterActiveUserIds(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<ReadonlySet<UserId>> {
  if (userIds.length === 0) return new Set();
  const rows = getDb()
    .select({ userId: members.userId })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        inArray(members.userId, [...userIds]),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .all();
  return new Set(rows.map((row) => row.userId as UserId));
}

/** Re-admits a former member: same row, active again, with the new invitation's terms. */
export async function reactivateMember(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
  invitedBy: UserId | null,
  at: IsoTimestamp,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({
      role,
      invitedBy,
      status: "active",
      joinedAt: at,
      archivedAt: null,
      updatedAt: at,
    })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

